enum Bound { Absent, Present(i32) }
impl Bound {
 fn resolve(self, fallback: i32) -> i32 {
  match self { Bound::Absent => fallback, Bound::Present(v) => v }
 }
}
fn allowed(value:i32, bound:Bound)->bool { value >= bound.resolve(0) }

